/**
 * Parses a URL query string into a plain object.
 * 
 * Rules:
 * - Optional leading "?".
 * - Pairs separated by "&"; empty pairs ignored.
 * - Split on first "="; key without "=" maps to "".
 * - "+" in key/value becomes space.
 * - Percent-decoding applies. If decoding fails, keep the raw text (with "+" already converted).
 * - Multiple values for the same key become an array.
 * - Safe against prototype pollution (keys like "__proto__" become own properties).
 */
export function parseQuery(query) {
  if (typeof query !== 'string') {
    return {};
  }

  // Remove optional leading "?"
  let str = query;
  if (str.startsWith('?')) {
    str = str.slice(1);
  }

  const result = Object.create(null);
  const parts = str.split('&');

  for (const part of parts) {
    if (part.length === 0) {
      continue;
    }

    // Split on the first "=" only
    const idx = part.indexOf('=');
    let key, value;

    if (idx === -1) {
      // No "=": key is the whole part, value is ""
      key = part;
      value = '';
    } else {
      key = part.slice(0, idx);
      value = part.slice(idx + 1);
    }

    // Decode "+" as space
    let decodedKey = key.replace(/\+/g, ' ');
    let decodedValue = value.replace(/\+/g, ' ');

    // Function to safely percent-decode
    const safeDecode = (s) => {
      // Replace + first (already done, but ensure no double replacement issues)
      // Then use decodeURIComponent. If it throws, return the string as-is.
      try {
        return decodeURIComponent(s);
      } catch {
        return s;
      }
    };

    // Apply percent-decoding
    decodedKey = safeDecode(decodedKey);
    decodedValue = safeDecode(decodedValue);

    // Handle multiple values
    if (decodedKey in result) {
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}
