/**
 * Deep equality check for JavaScript values.
 * Handles primitives, arrays, plain objects, Date, cyclic structures, etc.
 *
 * @param {*} a - First value
 * @param {*} b - Second value
 * @returns {boolean} - true if structurally equal, false otherwise
 */
export function deepEqual(a, b) {
  if (a === b) {
    // SameValueZero check: handles NaN === NaN and 0 === -0
    return true;
  }

  // Different types are not equal
  if (a instanceof Date && b instanceof Date) {
    return a.getTime() === b.getTime();
  }

  if (Array.isArray(a) && Array.isArray(b)) {
    if (a.length !== b.length) {
      return false;
    }
    for (let i = 0; i < a.length; i++) {
      if (!deepEqual(a[i], b[i])) {
        return false;
      }
    }
    return true;
  }

  // Check for plain object equality
  if (typeof a === 'object' && a !== null && typeof b === 'object' && b !== null) {
    // If either is not a plain object or an array, they are not equal (handled above for arrays)
    // We need to ensure they are both plain objects
    if (!isPlainObject(a) || !isPlainObject(b)) {
      return false;
    }

    const keysA = Object.keys(a);
    const keysB = Object.keys(b);

    if (keysA.length !== keysB.length) {
      return false;
    }

    const keysMap = new Map();
    for (const key of keysA) {
      keysMap.set(key, true);
    }

    for (const key of keysB) {
      if (!keysMap.has(key)) {
        return false;
      }
      if (!deepEqual(a[key], b[key])) {
        return false;
      }
    }

    return true;
  }

  // All other cases (including null vs number, etc.) are not equal
  return false;
}

/**
 * Checks if a value is a plain object (not an array, Date, or other special object).
 * @param {*} value - The value to check
 * @returns {boolean} - true if it is a plain object
 */
function isPlainObject(value) {
  if (typeof value !== 'object' || value === null) {
    return false;
  }
  const prototype = Object.getPrototypeOf(value);
  return prototype === null || prototype === Object.prototype;
}
