        throw new SyntaxError('SyntaxError: Expected closing parenthesis');
      }
      consume(); // consume ')'
      return val;
    }

    // Number
    if (c != null && (/\d/.test(c) || c === '.')) {
      return parseNumber();
    }

    throw new SyntaxError('SyntaxError: Unexpected character');
  };

  // Parse multiplicative expressions (* /)
  const parseMultiplicative = () => {
    let left = parsePrimary();

    while (true) {
      skipWhitespace();
      const op = peek();

      if (op === '*') {
        consume();
        skipWhitespace();
        const right = parsePrimary();
        left = left * right;
      } else if (op === '/') {
        consume();
        skipWhitespace();
        const right = parsePrimary();
        if (right === 0) {
          throw new RangeError('RangeError: Division by zero');
        }
        left = left / right;
      } else {
        break;
      }
    }

    return left;
  };

  // Parse additive expressions (+ -)
  const parseAdditive = () => {
    let left = parseMultiplicative();

    while (true) {
      skipWhitespace();
      const op = peek();

      if (op === '+') {
        consume();
        skipWhitespace();
        const right = parseMultiplicative();
        left = left + right;
      } else if (op === '-') {
        consume();
        skipWhitespace();
        const right = parseMultiplicative();
        left = left - right;
      } else {
        break;
      }
