/**
 * Finds the first and last index of a target value in a sorted array.
 * Uses binary search to achieve O(log n) time complexity.
 *
 * @param {number[]} sorted - An array of numbers sorted in ascending order.
 * @param {number} target - The number to find.
 * @returns {[number, number]} An array [first, last] where first and last are the indices
 *                             of the target, or [-1, -1] if the target is not found.
 */
export function searchRange(sorted, target) {
  // Handle empty array edge case
  if (sorted.length === 0) {
    return [-1, -1];
  }

  // Find the first occurrence
  let left = 0;
  let right = sorted.length - 1;
  let first = -1;

  while (left <= right) {
    const mid = left + Math.floor((right - left) / 2);
    if (sorted[mid] === target) {
      first = mid;
      right = mid - 1; // Try to find an earlier occurrence
    } else if (sorted[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  // If first is still -1, the target was not found
  if (first === -1) {
    return [-1, -1];
  }

  // Find the last occurrence
  left = 0;
  right = sorted.length - 1;
  let last = first; // We know a target exists at 'first', so we can start here

  while (left <= right) {
    const mid = left + Math.floor((right - left) / 2);
    if (sorted[mid] === target) {
      last = mid;
      left = mid + 1; // Try to find a later occurrence
    } else if (sorted[mid] < target) {
      left = mid + 1;
    } else {
      right = mid - 1;
    }
  }

  return [first, last];
}
